  $$('#so .so-btn').forEach(b => {
    const t = $('.so-t', b), logo = $('.so-logo', b), orig = t.textContent, logoHTML = logo.innerHTML;
    b.addEventListener('click', () => {
      if (b.classList.contains('busy')) return;
      b.classList.add('busy'); Sound.play('tab');
      logo.innerHTML = '<i class="bt-spin"></i>'; swapText(t, 'Connecting to ' + b.dataset.p);
      setTimeout(() => { b.classList.remove('busy'); b.classList.add('done'); logo.innerHTML = ic('check', 'sm icon-in'); swapText(t, 'Connected with ' + b.dataset.p); Sound.play('done'); }, 1300);
      setTimeout(() => { b.classList.remove('done'); logo.innerHTML = logoHTML; swapText(t, orig); }, 3400);
    });
  });
  $('#so-email').addEventListener('click', () => { Sound.play('tick'); showToast('Opening email sign-in'); });
}
